"""Periodic descent in action: transporting still lifes and orbits between lattice sizes.

For d dividing n, every configuration on the ring of d cells can be repeated around the ring
of n cells.  The resulting map

    pull : Config(d) -> Config(n),    (pull t)(i) = t(i mod d),

is the engine behind every uniform-in-n counting theorem of the theory.  It is

  * injective;
  * a SIMULATION EMBEDDING: it intertwines the dynamics of every rule, F_g(pull t) = pull(F_g t),
    so it is a morphism of dynamical systems and not merely a map of fixed-point sets;
  * period-preserving: a configuration and its pullback have the same EXACT orbit period.

Three consequences follow, and this script demonstrates each in turn:

  MONOTONICITY   #V(g,d) <= #V(g,n) whenever d | n, for every one of the 256 rules;
  DESCENT        if every fixed configuration on Z/n is d-periodic, then #V(g,n) = #V(g,d),
                 so one finite computation settles an infinite family of counting problems;
  TRANSPORT      an orbit of exact period k on Z/d gives an orbit of exact period k on Z/n.

Finally, the COPRIME COLLAPSE: when gcd(d, n) = 1, d-periodicity degenerates to constancy, so
the only surviving still lifes are the constant configurations that the rule happens to fix.

Pure Python 3, no dependencies.  Run:  python3 demo2.py
"""

from __future__ import annotations

from itertools import product
from math import gcd
from typing import Dict, List, Tuple

Neigh = Tuple[int, int, int]
Table = Dict[Neigh, int]
Config = Tuple[int, ...]

NEIGHBOURHOODS: List[Neigh] = [(a, b, c) for a in (0, 1) for b in (0, 1) for c in (0, 1)]


def rule_table(number: int) -> Table:
    return {(a, b, c): (number >> (4 * a + 2 * b + c)) & 1 for (a, b, c) in NEIGHBOURHOODS}


def step(t: Table, s: Config) -> Config:
    n = len(s)
    return tuple(t[(s[(i - 1) % n], s[i], s[(i + 1) % n])] for i in range(n))


def pull(t_small: Config, n: int) -> Config:
    """Repeat a configuration of length d around a ring of length n, for d | n."""
    d = len(t_small)
    if n % d:
        raise ValueError(f"{d} does not divide {n}")
    return tuple(t_small[i % d] for i in range(n))


def fixed_configs(number: int, n: int) -> List[Config]:
    t = rule_table(number)
    return [s for s in product((0, 1), repeat=n) if step(t, s) == s]


def exact_period(number: int, s: Config) -> int:
    """Least k > 0 with F^k(s) = s, or 0 if s is not periodic."""
    t = rule_table(number)
    cur, seen = s, {s}
    for k in range(1, 2 ** len(s) + 2):
        cur = step(t, cur)
        if cur == s:
            return k
        if cur in seen:
            return 0
        seen.add(cur)
    return 0


def show(s: Config) -> str:
    return "".join("#" if b else "." for b in s)


def banner(title: str) -> None:
    print("\n" + "=" * 74 + f"\n{title}\n" + "=" * 74)


def check(claim: str, ok: bool) -> None:
    print(f"  [{'OK ' if ok else 'FAIL'}]  {claim}")
    assert ok, claim


def demo_embedding() -> None:
    banner("1.  The pullback is an injective simulation embedding")
    for number in (110, 30, 90, 184, 51):
        for d, n in ((2, 8), (3, 12), (4, 16), (5, 15)):
            t = rule_table(number)
            small = list(product((0, 1), repeat=d))
            intertwines = all(step(t, pull(u, n)) == pull(step(t, u), n) for u in small)
            injective = len({pull(u, n) for u in small}) == len(small)
            periods = all(exact_period(number, pull(u, n)) == exact_period(number, u)
                          for u in small)
            check(f"rule {number:3d}, {d} | {n}: intertwines={intertwines}, "
                  f"injective={injective}, periods preserved={periods}",
                  intertwines and injective and periods)


def demo_monotonicity() -> None:
    banner("2.  Divisibility monotonicity, for all 256 rules")
    pairs = [(2, 4), (2, 6), (3, 6), (2, 8), (4, 8), (3, 9), (2, 10), (5, 10), (3, 12), (4, 12)]
    for d, n in pairs:
        ok = all(len(fixed_configs(r, d)) <= len(fixed_configs(r, n)) for r in range(256))
        check(f"#V(g,{d}) <= #V(g,{n}) for every one of the 256 rules", ok)


def demo_descent() -> None:
    banner("3.  Descent: one finite computation settles infinitely many lattice sizes")
    for number, d in ((150, 2), (90, 3), (30, 2)):
        base = len(fixed_configs(number, d))
        print(f"\n  Rule {number}: every fixed configuration is {d}-periodic; "
              f"base count on Z/{d} is {base}.")
        for n in range(d, 13, d):
            big = fixed_configs(number, n)
            all_periodic = all(all(s[(i + d) % n] == s[i] for i in range(n)) for s in big)
            from_small = {pull(u, n) for u in fixed_configs(number, d)}
            check(f"n = {n:2d}: #V = {len(big)} = base, all {d}-periodic = {all_periodic}, "
                  f"and every one is a pullback",
                  len(big) == base and all_periodic and set(big) == from_small)


def demo_transport() -> None:
    banner("4.  Transport of orbits: the Rule 110 two-cycle travels to every multiple of 4")
    seed: Config = (1, 1, 1, 0)
    t = rule_table(110)
    print(f"  On the ring of 4 cells:  {show(seed)}  ->  {show(step(t, seed))}"
          f"  ->  {show(step(t, step(t, seed)))}")
    check("the seed has exact period 2 on Z/4", exact_period(110, seed) == 2)
    for n in (4, 8, 12, 16, 20):
        s = pull(seed, n)
        p = exact_period(110, s)
        print(f"    n = {n:2d}:  {show(s)}   exact period {p}")
        check(f"exact period is still 2 on Z/{n}, and the configuration is not the fixed one",
              p == 2 and any(s))


def demo_collapse() -> None:
    banner("5.  Coprime collapse: when gcd(d, n) = 1, periodicity means constancy")
    for number, d in ((150, 2), (90, 3), (30, 2)):
        fixes = [c for c in (0, 1) if rule_table(number)[(c, c, c)] == c]
        print(f"\n  Rule {number}: period d = {d}; constant configurations fixed by the rule: "
              f"{len(fixes)} of 2.")
        for n in range(1, 14):
            if gcd(d, n) != 1:
                continue
            got = fixed_configs(number, n)
            consts = {(c,) * n for c in fixes}
            check(f"n = {n:2d} (coprime to {d}): #V = {len(got)} and the fixed set is exactly "
                  f"the {len(fixes)} constant configuration(s)",
                  set(got) == consts)


def main() -> None:
    print(__doc__)
    demo_embedding()
    demo_monotonicity()
    demo_descent()
    demo_transport()
    demo_collapse()
    banner("All descent checks passed.")


if __name__ == "__main__":
    main()
